<?php

namespace App\Actions\MealPlan;

use App\Models\Meal;
use App\Models\Recipe;
use App\Models\RecipeMealAssignment;
use App\Models\Tag;
use Carbon\CarbonInterface;
use Illuminate\Support\Collection;
use Illuminate\Support\Facades\DB;

/**
 * "Insert" on a week-review suggestion: puts the recipe into a free place of
 * the reviewed week as a single meal. The shopping list is not touched (it is
 * generated by hand).
 *
 * A free place is a day (today or later) and time of day with neither a
 * recipe nor a note, matching one of the recipe's meal labels (dinner when it
 * has none). Dinners are filled first, then suppers, lunches, breakfasts;
 * within one time of day the emptiest day wins.
 */
class InsertRecipeIntoPlan
{
    public const TYPE_PRIORITY = ['dinner', 'supper', 'lunch', 'breakfast', 'dessert'];

    /** @return array{assignment: RecipeMealAssignment, date: string, type: string}|null null when nothing is free */
    public function __invoke(Recipe $recipe, CarbonInterface $start): ?array
    {
        return DB::transaction(function () use ($recipe, $start) {
            $slot = $this->slotFor($recipe, $this->freeSlots($start));

            if ($slot === null) {
                return null;
            }

            $meal = Meal::query()->whereDate(Meal::DATE_COLUMN, $slot['date'])->where(Meal::TYPE_COLUMN, $slot['type'])->orderBy('id')->first()
                ?? Meal::query()->create(['date' => $slot['date'].' 12:00:00', 'type' => $slot['type']]);

            $assignment = RecipeMealAssignment::query()->create([
                'meal_id' => $meal->id,
                'recipe_id' => $recipe->id,
                'mode' => RecipeMealAssignment::MODE_SINGLE,
            ]);

            return ['assignment' => $assignment, 'date' => $slot['date'], 'type' => $slot['type']];
        });
    }

    /**
     * The first free place this recipe fits (its tags must be loadable).
     *
     * @param  Collection<int, array{date: string, type: string}>  $freeSlots  from freeSlots()
     * @return array{date: string, type: string}|null
     */
    public function slotFor(Recipe $recipe, Collection $freeSlots): ?array
    {
        $types = $recipe->tags
            ->filter(fn (Tag $tag) => $tag->isMealType())
            ->map(fn (Tag $tag) => mb_strtolower($tag->name))
            ->intersect(Meal::TYPES)
            ->all() ?: ['dinner'];

        return $freeSlots->first(fn (array $slot) => in_array($slot['type'], $types, true));
    }

    /**
     * Free places of the week starting at $start, best first.
     *
     * @return Collection<int, array{date: string, type: string}>
     */
    public function freeSlots(CarbonInterface $start): Collection
    {
        $from = $start->copy()->startOfDay()->max(now()->startOfDay());
        $end = $start->copy()->startOfDay()->addDays(BuildWeekReview::DAYS - 1)->endOfDay();

        if ($from->gt($end)) {
            return collect();
        }

        $taken = Meal::query()
            ->withCount('recipes')
            ->whereBetween(Meal::DATE_COLUMN, [$from, $end])
            ->get()
            ->filter(fn (Meal $meal) => $meal->recipes_count > 0 || filled($meal->note))
            ->groupBy(fn (Meal $meal) => $meal->date->toDateString())
            ->map(fn (Collection $meals) => $meals->pluck('type')->unique()->all());

        $slots = collect();

        for ($day = $from->copy(); $day->lte($end); $day = $day->addDay()) {
            $date = $day->toDateString();
            $takenTypes = $taken->get($date, []);

            foreach (self::TYPE_PRIORITY as $priority => $type) {
                if (! in_array($type, $takenTypes, true)) {
                    $slots->push(['date' => $date, 'type' => $type, 'order' => [$priority, count($takenTypes), $date]]);
                }
            }
        }

        return $slots->sortBy('order')->map(fn (array $slot) => ['date' => $slot['date'], 'type' => $slot['type']])->values();
    }
}
